local S = {elapsed=0, started=false, destroyed=false, nodes={}, texts={}, buttons={}, listeners={}, native={}, page=nil, build=false, ping=false, lastPhase=nil, lastGrowth=0, message="", messageUntil=0, settings={volume=0.8,shake=false}, applying=false, view=nil, routeKeys={}, audio={seen={},queue={},last={},ready=false}}
-- 音效：audio/ 里的每条音效在场景里是 RuntimeAudio/<名> 节点，从传入的节点沿父链往上找
local Sfx = {}

function Sfx.find(go, name)
  local t = go ~= nil and go.transform or nil
  while t ~= nil do
    local node = t:Find("RuntimeAudio/" .. name)
    if node ~= nil then return node end
    t = t.parent
  end
  return nil
end

-- 一次性音效：交给 RuntimeAudio 节点上那个 AudioSource 播，连按会叠着响；音量固定传 1
function Sfx.play(go, name)
  return pcall(function()
    local AudioSource = typeof(CS.UnityEngine.AudioSource)
    local node = Sfx.find(go, name)
    node.parent:GetComponent(AudioSource):PlayOneShot(node:GetComponent(AudioSource).clip, 1)
  end)
end

-- 循环音（awc audio add --loop 放入的）：在它自己的节点上开关；返回 AudioSource，可调 pitch
function Sfx.loop(go, name, on)
  local ok, source = pcall(function()
    local source = Sfx.find(go, name):GetComponent(typeof(CS.UnityEngine.AudioSource))
    if on and not source.isPlaying then
      source.enabled = true
      source:Play()
    elseif not on then
      source:Stop()
    end
    return source
  end)
  return ok and source or nil
end

local function sound(name,minimumInterval)
  local now=Time.time
  if now-(S.audio.last[name] or -100)<(minimumInterval or 0.08) then return end
  S.audio.last[name]=now
  Sfx.play(self.gameObject,name)
end
local function applyVolume()
  local n=Sfx.find(self.gameObject,"click")
  if not n then return end
  local ok,source=pcall(function() return n.parent:GetComponent(typeof(U.AudioSource)) end)
  if ok and source then
    if S.audio.baseVolume==nil then S.audio.baseVolume=source.volume end
    source.volume=S.audio.baseVolume*S.settings.volume
    S.audio.source=source
  end
end
