local function node(path)
  if S.nodes[path] ~= nil then return S.nodes[path] end
  if runtimeScope == nil then return nil end
  local go=runtimeScope:FindGameObject(path)
  if go ~= nil then S.nodes[path]=go else log:warnOnce("node:"..path,"UI节点缺失",path) end
  return go
end
local function visible(path,on)
  local go=node(path); if go then pcall(function() if go.activeSelf ~= on then go:SetActive(on) end end) end
end
local function label(path,value)
  local text=S.texts[path]
  if not text then local go=node(path); if go then text=go:GetComponent(typeof(UI.Text)); S.texts[path]=text end end
  if text then local v=tostring(value or ""); if text.text~=v then text.text=v end end
end
local function enable(path,on)
  local b=S.buttons[path]
  if not b then local go=node(path); if go then b=go:GetComponent(typeof(UI.Button)); S.buttons[path]=b end end
  if b then b.interactable=on end
end
local function message(value)
  S.message=tostring(value or ""); S.messageUntil=Time.time+3
end
local function host()
  if not runtimeScope then return nil end
  local h,why=runtimeScope:GetRuntimeHostScript("runtime-host.lua")
  if not h then log:warnOnce("host-unavailable","玩法主控不可用",why) end
  return h
end
local function send(payload,quiet)
  local combat=payload.kind=="attack"or payload.kind=="skill1"or payload.kind=="skill2"or payload.kind=="dash"or(payload.kind=="attackHold"and payload.value==true)
  if combat and (not S.view or S.view.phase~="WAVE_ACTIVE"or S.page~=nil)then return false end
  payload.sourceResourceId="ui-game"
  local h=host()
  if h==nil or type(h.SubmitGameAction)~="function" then
    if not quiet then message("正在连接战场，请稍候");sound("error",0.3) end
    return false
  end
  local ok,result=pcall(h.SubmitGameAction,payload)
  if not ok then
    log:warnOnce("action-error","界面操作未完成",result)
    if not quiet then message("操作未完成，请重试");sound("error",0.3) end
    return false
  end
  if type(result)=="table" and result.ok==false then
    if not quiet then message(reasons[result.reason] or result.message or result.reason or "当前无法操作");sound("error",0.3) end
    return false
  end
  return true
end
local function bind(path,callback)
  local go=node(path); if not go then return end
  local b=go:GetComponent(typeof(UI.Button)); if not b then return end
  S.buttons[path]=b
  local listener=function() sound("click",0.06); callback() end
  b.onClick:AddListener(listener)
  S.listeners[#S.listeners+1]={event=b.onClick,callback=listener}
end
local function bindAction(path,kind,fields)
  bind(path,function()
    local payload={kind=kind}
    if fields then for k,v in pairs(fields) do payload[k]=v end end
    if kind=="upgrade" or kind=="sell" then
      local selected=S.view and S.view.selectedSlot
      payload.slot=type(selected)=="table" and (selected.id or selected.slotId) or selected
    end
    send(payload)
  end)
end
local function stopHold()
  S.attackDown=false
  if S.attackSent then send({kind="attackHold",value=false},true) end
  S.attackSent=false
end
local function bindAttackHold()
  local go=node("combatRoot/attackBtn"); if not go then return end
  local b=go:GetComponent(typeof(UI.Button)); S.buttons["combatRoot/attackBtn"]=b
  local EventTrigger=CS.UnityEngine.EventSystems.EventTrigger
  local EventTriggerType=CS.UnityEngine.EventSystems.EventTriggerType
  local trigger=go:GetComponent(typeof(EventTrigger))
  if not trigger then trigger=go:AddComponent(typeof(EventTrigger)) end
  local down=EventTrigger.Entry()
  down.eventID=EventTriggerType.PointerDown
  local downFn=function(_) if b and b.interactable then S.attackDown=true end end
  down.callback:AddListener(downFn); trigger.triggers:Add(down)
  S.listeners[#S.listeners+1]={event=down.callback,callback=downFn}
  local up=EventTrigger.Entry()
  up.eventID=EventTriggerType.PointerUp
  local upFn=function(_) S.attackDown=false end
  up.callback:AddListener(upFn); trigger.triggers:Add(up)
  S.listeners[#S.listeners+1]={event=up.callback,callback=upFn}
end
function OnApplicationFocus(focused)
 if not focused then stopHold() end
