local function nativeState(go)
  if go==nil then return false end
  -- Unity can retain a Lua userdata after destroying its GameObject.
  local ok,active=pcall(function() return go.activeSelf end)
  return ok and type(active)=="boolean",active
end
local function rememberNative(go,active)
  local saved
  for i=#S.native,1,-1 do
    if not nativeState(S.native[i].go) then table.remove(S.native,i)
    elseif S.native[i].go==go then saved=S.native[i] end
  end
  if not saved then
    saved={go=go,active=active};S.native[#S.native+1]=saved
  end
  if saved.group then
    local live=pcall(function() local alpha=saved.group.alpha end)
    if not live then saved.group=nil end
  end
  if not saved.group then
    pcall(function()
      local group=go:GetComponent(typeof(U.CanvasGroup));local added=false
      if not group then group=go:AddComponent(typeof(U.CanvasGroup));added=true end
      saved.alpha=group.alpha;saved.blocksRaycasts=group.blocksRaycasts;saved.interactable=group.interactable
      saved.addedGroup=added;saved.group=group
    end)
  end
  return saved
end
local function hideNative(saved)
  if not nativeState(saved.go) then return end
  pcall(function()
    if saved.group then
      if saved.group.alpha~=0 then saved.group.alpha=0 end
      if saved.group.blocksRaycasts then saved.group.blocksRaycasts=false end
      if saved.group.interactable then saved.group.interactable=false end
    end
    if saved.go.activeSelf then saved.go:SetActive(false) end
  end)
end
local function setNativeHidden(hide)
  if not hide and S.nativeHidden==false then return end
  if hide and S.nativeHidden and Time.time<(S.nativeCheckAt or 0) then return end
  S.nativeHidden=hide
  S.nativeCheckAt=hide and Time.time+0.25 or 0
  local names={"Throw","Jump","HoldHands","StopHoldHands","Fly","StandUp"}
  for _,name in ipairs(names) do
    if hide then
      local ok,go=pcall(function()
        local button=CS.DouyinUIService.GetInteractionButton(CS.HandType.Right,CS.UIType[name])
        return button and button.gameObject or nil
      end)
      local live,active=nativeState(ok and go or nil)
      if live then
        -- CanvasGroup keeps it invisible even if the platform reactivates its
        -- GameObject after this script's update; remember each instance once.
        hideNative(rememberNative(go,active))
      end
    end
  end
  if not hide then
    for _,saved in ipairs(S.native) do
      if nativeState(saved.go) then
        pcall(function()
          if saved.group then
            saved.group.alpha=saved.alpha;saved.group.blocksRaycasts=saved.blocksRaycasts;saved.group.interactable=saved.interactable
            if saved.addedGroup then U.Object.Destroy(saved.group) end
          end
        end)
        pcall(function() saved.go:SetActive(saved.active) end)
      end
    end
    S.native={}
  end
end
local function number(v,default)
  return tonumber(v) or default or 0
end
local function whole(v)
  return tostring(math.floor(number(v)+0.0001))
end
local function cap(v)
  return string.upper(string.sub(v,1,1))..string.sub(v,2)
end
local function setPage(page)
  S.page=page
