local function renderRoute(theme,candidate)
  local prefix="pagesRoot/votePage/vote"..cap(theme).."Btn/"..theme
  local points=candidate and (candidate.route or candidate.points) or nil
  local key=candidate and tostring(candidate.seed)..":"..tostring(candidate.layoutHash or "") or "empty"
  if S.routeKeys[theme]==key then return end
  S.routeKeys[theme]=key
  local usable=type(points)=="table" and #points>=2
  local minX,maxX,minZ,maxZ=1e9,-1e9,1e9,-1e9
  if usable then
    for _,p in ipairs(points) do
      local x=number(p.x or p[1]); local z=number(p.z or p[2])
      minX=math.min(minX,x); maxX=math.max(maxX,x); minZ=math.min(minZ,z); maxZ=math.max(maxZ,z)
    end
  end
  local scale=math.min(197/math.max(1,maxX-minX),82/math.max(1,maxZ-minZ))
  local ox=(219-(maxX-minX)*scale)/2; local oy=(104-(maxZ-minZ)*scale)/2
  for i=1,16 do
    local path=prefix.."PreviewRoot/"..theme.."Route"..i
    local go=node(path)
    local show=usable and i<#points
    if go then
      go:SetActive(show)
      if show then
        local a,b=points[i],points[i+1]
        local x1=(number(a.x or a[1])-minX)*scale+ox
        local y1=(number(a.z or a[2])-minZ)*scale+oy
        local x2=(number(b.x or b[1])-minX)*scale+ox
        local y2=(number(b.z or b[2])-minZ)*scale+oy
        local dx,dy=x2-x1,y2-y1
        local rect=go:GetComponent(typeof(U.RectTransform))
        if rect then
          -- 预览父容器局部左上角为原点，正y向下。
          rect.anchorMin=U.Vector2(0,1); rect.anchorMax=U.Vector2(0,1); rect.pivot=U.Vector2(0,0.5)
          rect.anchoredPosition=U.Vector2(x1,-y1)
          rect.sizeDelta=U.Vector2(math.sqrt(dx*dx+dy*dy),5)
          rect.localEulerAngles=U.Vector3(0,0,-math.deg(math.atan(dy,dx)))
        end
      end
    end
  end
end
local function candidatesByTheme(v)
  local result={}
  if type(v.candidates)=="table" then
    for _,c in pairs(v.candidates) do if type(c)=="table" then result[c.id or c.theme or c.themeId]=c end end
  end
  return result
end
local function updateTower(v)
  local vote=v.saleVote
  if vote and vote.requester~=v.localPlayerId and S.saleNotice~=vote.id then
   S.saleNotice=vote.id;S.build=true;S.ping=false;S.page=nil
  end
  local selected=v.selectedSlot
  local slot=type(selected)=="table" and (selected.id or selected.slotId) or selected
  label("buildPanelRoot/buildTitle",slot and ("塔位 "..whole(slot))or "防御塔")
  local economic=not v.anyTowerSlot and number(slot)==number(v.slotCount,24)
  local t=v.tower
  local occupied=type(t)=="table" and (t.type or t.family or t.towerType)~=nil
  local quota=v.buildQuota
  local remaining=quota and (math.max(0,quota.base-quota.owned)+quota.extra)or 0
  label("buildPanelRoot/buildSubtitle",occupied and "团队防御塔"or ("团队还可建 "..remaining.." 座"))
  visible("buildPanelRoot/buildCatalogRoot",not occupied)
  visible("buildPanelRoot/towerDetailRoot",occupied)
  local gold=number(v.gold)
  for _,kind in ipairs({"crossbow","prism","mortar","slow","barrier","economy"}) do
    local validType=v.anyTowerSlot or (economic and kind=="economy") or (not economic and kind~="economy")
    enable("buildPanelRoot/buildCatalogRoot/build"..cap(kind).."Btn",not occupied and slot~=nil and v.canBuild~=false and validType and gold>=towerCosts[kind][1])
  end
  visible("buildPanelRoot/towerDetailRoot/contributeBtn",false)
  if not occupied then return end
  local family=t.type or t.family or t.towerType
  local tier=number(t.tier or t.level,1)
  local costs=towerCosts[family] or {0,0,0,0,0}
  local names=branchNames[family] or {"专精 A","专精 B"}
  local name=t.name or towerNames[family] or "防御塔"
  label("buildPanelRoot/towerDetailRoot/towerName",name.."  ·  "..(tier>=4 and (t.branch=="b" and "IV-B" or "IV-A") or tostring(tier).."级"))
  label("buildPanelRoot/towerDetailRoot/towerDescription",t.nextBenefit or t.description or "")
  visible("buildPanelRoot/towerDetailRoot/upgradeModesRoot/linearUpgradePage",tier~=3)
  visible("buildPanelRoot/towerDetailRoot/upgradeModesRoot/branchUpgradePage",tier==3)
  local price=number(t.nextCost,costs[math.min(4,tier+1)])
  label("buildPanelRoot/towerDetailRoot/upgradeModesRoot/linearUpgradePage/upgradeBtn/upgradeBtnLabel",tier>=4 and "已达最高等级" or ("升级 · "..whole(price)))
  enable("buildPanelRoot/towerDetailRoot/upgradeModesRoot/linearUpgradePage/upgradeBtn",tier<3 and gold>=price and t.canUpgrade~=false)
  for idx,branch in ipairs({"A","B"}) do
    local p="buildPanelRoot/towerDetailRoot/upgradeModesRoot/branchUpgradePage/branch"..branch.."Btn"
    local cost=number(idx==1 and t.branchACost or t.branchBCost,costs[idx+3])
    label(p.."/branch"..branch.."BtnLabel",names[idx].." "..whole(cost))
    enable(p,gold>=cost and t.canUpgrade~=false)
  end
  visible("buildPanelRoot/towerDetailRoot/contributeBtn",false)
  visible("buildPanelRoot/towerDetailRoot/upgradeModesRoot/linearUpgradePage/upgradeBtn/priceCoin",tier<4)

  enable("buildPanelRoot/towerDetailRoot/sellBtn",t.canSell==true and not t.sellWaiting)
  label("buildPanelRoot/towerDetailRoot/sellBtn/sellBtnLabel",t.sellLabel or "拆除")
end
local function updateAudio(v,phase)
  local a=S.audio
  local initialized=a.ready
  if initialized then
    if a.phase~=phase then
      if phase=="RANKING" then sound("start",1)
      elseif phase=="WAVE_ACTIVE" then sound("wave",1)
      elseif phase=="RESULT" then
        local r=v.result
        local won=type(r)=="table" and (r.won==true or r.outcome=="victory") or r=="victory"
        sound(won and "victory" or "defeat",2)
      end
    elseif phase=="WAVE_ACTIVE" and a.wave~=v.wave then sound("wave",1) end
    if a.gold~=nil and v.gold~=nil and tonumber(v.gold) and tonumber(v.gold)>a.gold then sound("coin",0.8) end
    if a.hp~=nil and v.hp~=nil then
      local hp=number(v.hp)
      if hp<a.hp and a.hp>0 then sound("hurt",0.4)
      elseif hp>0 and a.hp<=0 and (phase=="WAVE_ACTIVE" or phase=="INTERMISSION") then sound("revive",1) end
    end
  end
  for _,e in ipairs(type(v.effects)=="table" and v.effects or {}) do
    local id=tostring(e.id or "")
    if id~="" and not a.seen[id] then
      a.seen[id]=true;a.queue[#a.queue+1]=id
      if initialized and v.localPlayerId~=nil and tostring(e.owner)==tostring(v.localPlayerId) then
        local kind=e.kind
        if kind=="skill1" or kind=="hero-skill1" then kind=v.loadout=="ranged" and "hero-magic" or "hero-heavy" end
        if kind=="hero-melee" and (e.ability=="skill1" or e.skill=="skill1") then kind="hero-heavy" end
        if kind=="hero-melee" or kind=="hero-ranged" or kind=="hero-heavy" or kind=="hero-magic" or kind=="dash" then sound(kind,0.09) end
      end
    end
  end
  while #a.queue>256 do a.seen[table.remove(a.queue,1)]=nil end
  a.phase=phase;a.wave=v.wave;a.gold=tonumber(v.gold);a.hp=tonumber(v.hp);a.ready=true
end
-- Runtime presentation patch; preserves the editor's authored bindings and audio.
local function rect(path,x,y,w,h)
 local go=path;if type(path)=="string" then go=node(path)end;if not go then return end
 local r=go:GetComponent(typeof(U.RectTransform));if not r then return end
 r.anchorMin=U.Vector2(0,1);r.anchorMax=U.Vector2(0,1);r.pivot=U.Vector2(0,1)
 r.anchoredPosition=U.Vector2(x,-y);r.sizeDelta=U.Vector2(w,h);r.localScale=U.Vector3(1,1,1)
end
local function color(r,g,b,a)return U.Color(r/255,g/255,b/255,a or 1)end
local ink=color(36,29,53)
local palette={color(255,192,65),color(112,185,251),color(190,135,245),color(100,213,188),color(244,128,130),color(255,210,87)}
local function makeSkin(round)
 local n=128;local tex=U.Texture2D(n,n,U.TextureFormat.RGBA32,false)
 for y=0,n-1 do for x=0,n-1 do
  local dx,dy=math.abs((x+.5)*64/n-32),math.abs((y+.5)*64/n-32)
  local d=round and math.sqrt(dx*dx+dy*dy)-30 or math.sqrt(math.max(dx-21,0)^2+math.max(dy-21,0)^2)-9
  local c=U.Color(0,0,0,0)
  if d<=0 then
   if d> -3 then c=ink
   elseif y<n*9/64 then c=color(157,145,130)
   elseif y>n*48/64 then c=color(255,255,255)
   else c=color(232,225,214) end
  end
  if d<=0 then c.a=math.min(1,-d*n/64)end
  tex:SetPixel(x,y,c)
 end end
 tex:Apply();tex.filterMode=U.FilterMode.Bilinear
 local sprite=U.Sprite.Create(tex,U.Rect(0,0,n,n),U.Vector2(.5,.5),100,0,U.SpriteMeshType.FullRect,round and U.Vector4(0,0,0,0) or U.Vector4(24,24,24,24))
 S.cartoonAssets=S.cartoonAssets or {};S.cartoonAssets[#S.cartoonAssets+1]=sprite;S.cartoonAssets[#S.cartoonAssets+1]=tex
 return sprite
end
