 local go=node(path);if not go then return end
 local im=go:GetComponent(typeof(UI.Image));if not im then return end
 im.sprite=round and S.circleSprite or S.panelSprite;im.type=round and UI.Image.Type.Simple or UI.Image.Type.Sliced
 im.color=c or color(255,244,217);im.raycastTarget=false
end
