 t.fontSize=size;t.fontStyle=U.FontStyle.Bold;t.color=c or U.Color.white
 t.alignment=center and U.TextAnchor.MiddleCenter or U.TextAnchor.MiddleLeft
 t.resizeTextForBestFit=true;t.resizeTextMinSize=math.max(12,size-4);t.resizeTextMaxSize=size
 local outline=go:GetComponent(typeof(UI.Outline)) or go:AddComponent(typeof(UI.Outline))
 outline.effectColor=ink;outline.effectDistance=U.Vector2(1.5,-1.5)
