local function fitButton(path,w,h,c,circle)
 local go=node(path);if not go then return end
 local b=go:GetComponent(typeof(UI.Button))
 for i=0,go.transform.childCount-1 do
  local child=go.transform:GetChild(i);local name=tostring(child.name)
