local function uiHit(x,y,allowNativeTap)
 local v=S.view;if not v then return true end
 if S.page or v.phase=="LOBBY" or v.phase=="RANKING" or v.phase=="RESULT" then return true end
 local point=U.Vector2(x,y)
 for _,path in ipairs({"topHudRoot","utilityRoot","entryRoot/pingEntryBtn","readyBtn","combatRoot/attackBtn","combatRoot/skillOneBtn","combatRoot/skillTwoBtn","combatRoot/dashBtn","combatRoot/reviveBtn","buildPanelRoot","pingPanelRoot"})do
  local go=node(path)
  if go and go.activeInHierarchy then
   local r=go:GetComponent(typeof(U.RectTransform))
   if r and U.RectTransformUtility.RectangleContainsScreenPoint(r,point,nil)then return true end
  end
 end
 local camera=CS.DouyinCameraService.GetCamera();local r=camera and camera.pixelRect
 -- Native joystick and chat/emote area remain owned by the platform.
 if r then local nx=(x-r.x)/r.width;local ny=(y-r.y)/r.height
  if (not allowNativeTap and nx<.3 and ny<.40)or(nx>.34 and nx<.59 and ny<.15)then return true end
 end
 return false
end
