local function bestiaryPortrait(b,entry)
 if b.asset==entry.asset then return end
 local source=U.GameObject.Find(entry.asset)
 if not source and entry.kind=="basic"then source=U.GameObject.Find("CrystalDefenseRiftSource")end
 local mf=source and source:GetComponentInChildren(typeof(U.MeshFilter),true)
 local renderer=mf and mf.gameObject:GetComponent(typeof(U.MeshRenderer))
 if b.bakedMesh then U.Object.Destroy(b.bakedMesh);b.bakedMesh=nil end
 if not mf or not renderer then
  local skin=source and source:GetComponentInChildren(typeof(U.SkinnedMeshRenderer),true)
  if skin and skin.sharedMesh then
   local baked=U.Mesh();skin:BakeMesh(baked);baked:RecalculateBounds();b.bakedMesh=baked
   mf={sharedMesh=baked};renderer=skin
  end
 end
