local function refresh(v)
  S.view=v
  local phase=tostring(v.phase or "LOBBY")
  updateAudio(v,phase)
  if S.lastPhase~=phase then
    if phase=="RESULT" or phase=="LOBBY" or phase=="RANKING" then S.page=nil; S.build=false; S.ping=false end
    stopHold(); S.lastPhase=phase
  end
  local battle=phase=="WAVE_ACTIVE" or phase=="PREPARE" or phase=="INTERMISSION"
  local growth=number(v.growthPoints)
  if growth>0 and phase=="INTERMISSION" then S.page="growth";S.build=false;S.ping=false end
  S.lastGrowth=growth
  local page=S.page
  local cameraHost=host();if cameraHost and cameraHost.SetCameraUiBlocked then cameraHost.SetCameraUiBlocked(page~=nil or not battle) end
  if page==nil then
    if phase=="LOBBY" then page="lobby" elseif phase=="RANKING" then page="vote" elseif phase=="MAIN_CLEAR"then page="result" elseif phase=="RESULT" then page="result" end
  end
  visible("pagesRoot",page~=nil)
  for _,p in ipairs({"lobby","vote","growth","settings","result"}) do visible("pagesRoot/"..p.."Page",page==p) end
  visible("heroHudRoot",battle)
  visible("combatRoot",battle and page==nil)
  visible("entryRoot",battle)
  visible("readyBtn",(phase=="PREPARE" or phase=="INTERMISSION") and page==nil)
  label("readyBtn/readyBtnLabel",v.isReady and ("已准备 "..whole(v.readyCount).."/"..whole(v.readyTotal))or "准备好了")
  enable("readyBtn",not v.isReady)
  visible("buildPanelRoot",battle and S.build and page==nil)
  visible("pingPanelRoot",battle and S.ping and page==nil)
  setNativeHidden(true)
  if not battle or page~=nil then stopHold() end
  label("topHudRoot/coreValue",whole(v.coreHp).." / "..whole(v.coreMax or 20))
  label("topHudRoot/waveValue",number(v.wave)>0 and (whole(v.wave)..(v.endless and " · 无尽"or" / 24")) or "准备")
  label("topHudRoot/goldValue",v.gold~=nil and whole(v.gold) or "—")
  label("topHudRoot/phaseValue",phases[phase] or phase)
  local msg=v.message or ((phase=="PREPARE" or phase=="INTERMISSION") and ("下一波将在 "..whole(v.phaseLeft).." 秒后开始") or "守住路线，注意漏怪。")
  if Time.time<S.messageUntil then msg=S.message end
  label("messageRoot/messageText",msg)
  local melee=(v.loadout=="melee");local hero=HERO_UI[v.loadout]or HERO_UI.melee
  label("heroHudRoot/heroClassText","仔仔 · "..hero.name)
  label("heroHudRoot/heroHpText","生命 "..whole(v.hp).." / "..whole(v.maxHp))
  if S.healthFill then S.healthFill.fillAmount=math.max(0,math.min(1,number(v.hp)/math.max(1,number(v.maxHp,1)))) end
  label("entryRoot/growthEntryBtn/growthEntryBtnLabel",growth>0 and ("成长 · "..whole(growth)) or "英雄成长")
  for _,kind in ipairs({"melee","ranged","mage"})do
   local h=HERO_UI[kind];local selected=v.loadout==kind;local path="pagesRoot/lobbyPage/"..kind.."Btn"
   label(path.."/"..kind.."BtnLabel",(selected and "✓ 已选 · "or "")..h.name)
   buttonArt(path,(selected and "gold"or h.tone).."_rect")
  end
  local cooldowns=v.cooldowns or {}
  local skillNames={skillOne=hero.skill1,skillTwo=hero.skill2,dash="闪现",attack="普攻"}
  for id,key in pairs({skillOne="skill1",skillTwo="skill2",dash="dash",attack="attack"}) do
    local cd=number(cooldowns[key])
    label("combatRoot/"..id.."Btn/"..id.."Label",cd>0.05 and string.format("%.1fs",cd) or skillNames[id])
    enable("combatRoot/"..id.."Btn",phase=="WAVE_ACTIVE" and page==nil and number(v.hp)>0 and (id=="attack" or cd<=0.05))
  end
  local rescue=number(v.reviveProgress)
  visible("combatRoot/reviveBtn",v.reviveTarget~=nil or rescue>0)
  label("combatRoot/reviveBtn/reviveLabel",rescue>0 and ("援助 "..whole(math.min(1,rescue)*100).."%") or "援助队友")
  enable("combatRoot/reviveBtn",v.reviveTarget~=nil and number(v.hp)>0 and rescue<=0)
  updateTower(v)
  updateCartoon(v)
  updateV5(v)
  for _,choice in ipairs({"Damage","Health","Cooldown"}) do enable("pagesRoot/growthPage/growth"..choice.."Btn",growth>0) end
  local result=v.result
  local won=type(result)=="table" and (result.won==true or result.outcome=="victory") or result=="victory"
  label("pagesRoot/resultPage/resultTitle",won and "晶核守住了" or "这次远征结束了")
