local function dismissOutside()
 local function inside(go,pos)
  return go and go.activeInHierarchy and U.RectTransformUtility.RectangleContainsScreenPoint(go:GetComponent(typeof(U.RectTransform)),pos,nil)
 end
 local panel=S.bestiaryOpen and S.bestiary and S.bestiary.paper or(S.build and node("buildPanelRoot")or(S.ping and node("pingPanelRoot")or(S.page and node("pagesRoot"))))
 if not panel then S.dismissTouch=nil;return end
 local I=U.Input;local pos,began,ended,canceled,id
 if I.touchCount>1 then S.dismissTouch=nil;return end
 if I.touchCount==1 then local t=I.GetTouch(0);pos=t.position;began=t.phase==U.TouchPhase.Began;ended=t.phase==U.TouchPhase.Ended;canceled=t.phase==U.TouchPhase.Canceled;id=t.fingerId
 else pos=I.mousePosition;began=I.GetMouseButtonDown(0);ended=I.GetMouseButtonUp(0);id=-1 end
 if began then S.dismissTouch={x=pos.x,y=pos.y,id=id,panel=panel,outside=not inside(panel,pos)}end
 local d=S.dismissTouch
 if d and ((pos.x-d.x)^2+(pos.y-d.y)^2>100 or canceled)then S.dismissTouch=nil;return end
 if ended and d then
  S.dismissTouch=nil
  if d.id==id and d.panel==panel and d.outside and not inside(panel,pos)then
   if S.bestiaryOpen then S.bestiary.seen[S.bestiary.key]=true else S.build=false;S.ping=false;S.page=nil end
  end
 end
end

function Update()
  if S.destroyed or not S.started then return end
  dismissOutside()
  if S.nativeHidden then setNativeHidden(true) end
  if S.attackDown~=S.attackSent then
    local held=S.attackDown==true
    if send({kind="attackHold",value=held},true) then S.attackSent=held end
  end
  S.elapsed=S.elapsed+Time.deltaTime
  if S.elapsed<math.max(0.05,number(RefreshInterval,0.1)) then return end
  S.elapsed=0
  local h=host()
  if not h or type(h.GetGameView)~="function" then label("messageRoot/messageText","正在连接战场…");return end
  local ok,v=pcall(h.GetGameView)
  if not ok or type(v)~="table" then
    log:warnOnce("view-unavailable","战场视图尚未就绪",v)
    label("messageRoot/messageText","战场状态正在同步…")
    return
  end
  refresh(v)
  applyParchment(v)
  updateBestiary(v)
  updateRankingPanel(v)
  styleStoryOverlay(S.bestiary);styleStoryOverlay(S.rankPanel)
end
