-- Pooled, non-interactive damage labels projected from the actual hit position.
local function updateDamageNumbers()
 local h=host();if not h or not h.GetRenderState then return end
 local state=h.GetRenderState();if not state then return end
 local root=self.gameObject:GetComponent(typeof(U.RectTransform))
 local camera=CS.DouyinCameraService.GetCamera();local arena=h.GetArenaRoot and h.GetArenaRoot()
 if not root or not camera or not arena then return end
 local d=S.damageNumbers
 if not d then d={seen={},active={},pool={},round=state.round,primed=false};S.damageNumbers=d end
 if d.round~=state.round then
  for _,f in ipairs(d.active)do f.go:SetActive(false);d.pool[#d.pool+1]=f end
  d.active={};d.seen={};d.round=state.round;d.primed=false
 end
 local now=Time.time;local gameTime=h.GetPresentationTime and h.GetPresentationTime()or state.t
 for _,e in ipairs(state.effects or {})do
  if e.kind=="damage-number" and not d.seen[e.id]then
   d.seen[e.id]=now
   if d.primed and gameTime-e.t0<.55 and e.amount and e.amount>0 then
    local f=table.remove(d.pool)
    if not f and #d.active>=40 then f=table.remove(d.active,1)end
    if not f then
     local source=node("topHudRoot/goldValue")
     if source then
      local go=U.Object.Instantiate(source);go.name="DamageNumber";go.transform:SetParent(self.transform,false)
      local text=go:GetComponent(typeof(UI.Text))
      text.raycastTarget=false;text.resizeTextForBestFit=false;text.fontStyle=U.FontStyle.Bold;text.alignment=U.TextAnchor.MiddleCenter
      text.horizontalOverflow=U.HorizontalWrapMode.Overflow;text.verticalOverflow=U.VerticalWrapMode.Overflow
      local outline=go:GetComponent(typeof(UI.Outline))or go:AddComponent(typeof(UI.Outline))
      outline.effectColor=color(20,17,38);outline.effectDistance=U.Vector2(2,-2)
      f={go=go,text=text};S.created=S.created or {};S.created[#S.created+1]=go
     end
    end
    if f then
     f.x=e.x;f.z=e.z;f.start=now;f.hero=e.hero;f.magic=e.family=="magic"
     f.height=({child=1.1,runner=1.65,basic=2.1,guard=2.8,caster=2.6,boss=4.3})[e.enemyType]or 2.2
     f.drift=((e.id%5)-2)*13;f.text.fontSize=e.hero and 38 or 30
     f.text.text=e.amount<1 and string.format("%.1f",e.amount)or tostring(math.floor(e.amount+.5))
     f.go:SetActive(true);d.active[#d.active+1]=f
    end
   end
  end
 end
 d.primed=true
 for id,at in pairs(d.seen)do if now-at>5 then d.seen[id]=nil end end
 for i=#d.active,1,-1 do
  local f=d.active[i];local q=(now-f.start)/.85
  if q>=1 then f.go:SetActive(false);d.pool[#d.pool+1]=f;table.remove(d.active,i)
  else
   local y=(h.GroundY and h.GroundY(f.x,f.z)or 0)+f.height
   local wp=arena:TransformPoint(U.Vector3(f.x,y,f.z));local vp=camera:WorldToViewportPoint(wp)
   f.go:SetActive(not S.page and visibleDepth(vp) and vp.x>0 and vp.x<1 and vp.y>0 and vp.y<1)
   rect(f.go,vp.x*root.rect.width-80+f.drift*q,(1-vp.y)*root.rect.height-40-58*q,160,70)
   local scale=1+.23*math.sin(math.min(1,q/.22)*math.pi)
   f.go.transform.localScale=U.Vector3(scale,scale,1)
   local alpha=math.min(1,(1-q)/.30)
   f.text.color=f.magic and color(223,168,255,alpha)or (f.hero and color(255,228,124,alpha)or color(255,250,224,alpha))
  end
 end
end

