 if S.started and not S.destroyed then compactNameplate()end
  if S.started and not S.destroyed and S.view and not S.page and (S.view.phase=="PREPARE" or S.view.phase=="WAVE_ACTIVE" or S.view.phase=="INTERMISSION") then
    local actor=CS.DouyinActorService.GetLocalActor();local camera=CS.DouyinCameraService.GetCamera()
    local root=self.gameObject:GetComponent(typeof(U.RectTransform))
