      local p=camera:WorldToViewportPoint(U.Vector3(head.x,head.y+.28,head.z))
      rect("heroHudRoot",p.x*root.rect.width-59,(1-p.y)*root.rect.height-62,118,39)
      visible("heroHudRoot",visibleDepth(p) and p.x>0 and p.x<1 and p.y>0 and p.y<1)
    end
  end
