  for _,go in ipairs(S.created or {})do U.Object.Destroy(go)end
  for _,asset in ipairs(S.cartoonAssets or {})do U.Object.Destroy(asset)end
  for _,item in ipairs(S.listeners) do pcall(function() item.event:RemoveListener(item.callback) end) end
  S.listeners={}
  setNativeHidden(false)
  if S.audio.source and S.audio.baseVolume~=nil then pcall(function() S.audio.source:Stop(); S.audio.source.volume=S.audio.baseVolume end) end
end
